CREATE FUNCTION platform.catalog_timestamp(value TIMESTAMPTZ) RETURNS TEXT LANGUAGE SQL IMMUTABLE PARALLEL SAFE AS $$ SELECT to_char(value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') $$;
CREATE FUNCTION platform.catalog_author_json(value TEXT) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT jsonb_strip_nulls(a.metadata || jsonb_build_object('id',a.id,'group','author','name',a.name,'created_at',platform.catalog_timestamp(a.created_at),'updated_at',platform.catalog_timestamp(a.updated_at),'locked',a.locked,'version',a.version)) FROM platform.catalog_authors a WHERE a.id=value AND a.deleted_at IS NULL
$$;
CREATE FUNCTION platform.catalog_thread_json(kind TEXT,value TEXT) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT jsonb_build_object('id',t.id,'created_at',platform.catalog_timestamp(t.created_at),'updated_at',platform.catalog_timestamp(t.updated_at),'subject',t.subject,'body',t.body,'locked',t.locked,'relationships',jsonb_build_object('author',jsonb_build_object('id',t.author_id,'name',t.author_name,'version',1),'stats',jsonb_build_object('replies',0,'up',0,'down',0))) FROM platform.catalog_threads t WHERE t.entity_type=kind AND t.entity_id=value
$$;
CREATE FUNCTION platform.catalog_group_json(value TEXT) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT jsonb_strip_nulls(g.metadata || jsonb_build_object('id',g.id,'name',g.name,'created_at',platform.catalog_timestamp(g.created_at),'updated_at',platform.catalog_timestamp(g.updated_at),'locked',g.locked,'inactive',g.inactive,'version',g.version,'relationships',jsonb_build_object('members',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',gm.user_id,'name',gm.name,'version',1,'is_leader',gm.is_leader,'is_officer',gm.is_officer) ORDER BY gm.is_leader DESC,gm.name,gm.user_id) FROM platform.catalog_group_members gm WHERE gm.group_id=g.id),'[]'::jsonb),'thread',platform.catalog_thread_json('group',g.id),'stats',jsonb_build_object('chapters',(SELECT count(*) FROM platform.catalog_chapter_groups cg JOIN platform.catalog_chapters c ON c.id=cg.chapter_id WHERE cg.group_id=g.id AND c.deleted_at IS NULL))))) FROM platform.catalog_groups g WHERE g.id=value AND g.deleted_at IS NULL
$$;
CREATE FUNCTION platform.catalog_cover_json(value TEXT) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT jsonb_strip_nulls(jsonb_build_object('id',c.id,'created_at',platform.catalog_timestamp(c.created_at),'updated_at',platform.catalog_timestamp(c.updated_at),'ext',c.ext,'dimensions',c.dimensions,'volume',c.volume,'language',c.language,'description',c.description,'version',c.version,'relationships',jsonb_build_object('uploader',jsonb_build_object('id',c.uploader_id,'name',c.uploader_name,'version',1)))) FROM platform.catalog_covers c WHERE c.id=value AND c.deleted_at IS NULL
$$;
CREATE FUNCTION platform.catalog_manga_base(value TEXT) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT jsonb_strip_nulls((m.metadata - 'links') || jsonb_build_object('id',m.id,'created_at',platform.catalog_timestamp(m.created_at),'updated_at',platform.catalog_timestamp(m.updated_at),'published_at',platform.catalog_timestamp(m.published_at),'deleted_at',platform.catalog_timestamp(m.deleted_at),'state',m.state,'title',m.title,'year',m.year,'language',m.language,'demographic',m.demographic,'status',m.publication_status,'content_rating',m.content_rating,'locked',m.locked,'version',m.version)) FROM platform.catalog_manga m WHERE m.id=value
$$;
CREATE FUNCTION platform.catalog_manga_tags_json(value TEXT) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',t.id,'group',t.tag_group,'name',t.name) ORDER BY t.tag_group,t.name,t.id),'[]'::jsonb) FROM platform.catalog_manga_tags mt JOIN platform.catalog_tags t ON t.id=mt.tag_id WHERE mt.manga_id=value
$$;
CREATE FUNCTION platform.catalog_relations_json(value TEXT) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT COALESCE(jsonb_agg(platform.catalog_manga_base(m.id) || jsonb_build_object('type',r.relation_type,'relationships',jsonb_strip_nulls(jsonb_build_object('tags',platform.catalog_manga_tags_json(m.id),'cover',(SELECT platform.catalog_cover_json(c.id) FROM platform.catalog_covers c WHERE c.manga_id=m.id AND c.deleted_at IS NULL ORDER BY c.is_main DESC,c.created_at DESC,c.id LIMIT 1)))) ORDER BY r.relation_type,m.title,m.id),'[]'::jsonb) FROM platform.catalog_relations r JOIN platform.catalog_manga m ON m.id=r.related_id WHERE r.manga_id=value AND m.state='published' AND m.deleted_at IS NULL
$$;
CREATE FUNCTION platform.catalog_manga_json(value TEXT) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT platform.catalog_manga_base(m.id) || jsonb_build_object('relationships',jsonb_strip_nulls(jsonb_build_object(
 'submitter',jsonb_build_object('id',m.owner_id,'name',m.owner_name,'version',1),
 'cover',(SELECT platform.catalog_cover_json(c.id) FROM platform.catalog_covers c WHERE c.manga_id=m.id AND c.deleted_at IS NULL ORDER BY c.is_main DESC,c.created_at DESC,c.id LIMIT 1),
 'tags',platform.catalog_manga_tags_json(m.id),
 'authors',COALESCE((SELECT jsonb_agg(platform.catalog_author_json(a.id) ORDER BY a.name,a.id) FROM platform.catalog_manga_creators mc JOIN platform.catalog_authors a ON a.id=mc.author_id WHERE mc.manga_id=m.id AND mc.role='author' AND a.deleted_at IS NULL),'[]'::jsonb),
 'artists',COALESCE((SELECT jsonb_agg(platform.catalog_author_json(a.id) ORDER BY a.name,a.id) FROM platform.catalog_manga_creators mc JOIN platform.catalog_authors a ON a.id=mc.author_id WHERE mc.manga_id=m.id AND mc.role='artist' AND a.deleted_at IS NULL),'[]'::jsonb),
 'links',m.metadata->'links','relations',platform.catalog_relations_json(m.id),'thread',platform.catalog_thread_json('manga',m.id),
 'available_languages',COALESCE((SELECT jsonb_agg(x.language ORDER BY x.language) FROM (SELECT DISTINCT c.language FROM platform.catalog_chapters c WHERE c.manga_id=m.id AND c.deleted_at IS NULL AND NOT c.is_unavailable)x),'[]'::jsonb),
 'available_groups',COALESCE((SELECT jsonb_agg(platform.catalog_group_json(x.group_id) ORDER BY x.group_id) FROM (SELECT DISTINCT cg.group_id FROM platform.catalog_chapter_groups cg JOIN platform.catalog_chapters c ON c.id=cg.chapter_id WHERE c.manga_id=m.id AND c.deleted_at IS NULL)x),'[]'::jsonb),
 'stats',jsonb_build_object('chapters',(SELECT count(*) FROM platform.catalog_chapters c WHERE c.manga_id=m.id AND c.deleted_at IS NULL),'views',COALESCE(s.views,0),'follows',COALESCE(s.follows,0))))) FROM platform.catalog_manga m LEFT JOIN platform.catalog_manga_counters s ON s.manga_id=m.id WHERE m.id=value
$$;
CREATE FUNCTION platform.catalog_chapter_json(value TEXT) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT jsonb_strip_nulls(c.metadata || jsonb_build_object('id',c.id,'source_id',c.source_id,'created_at',platform.catalog_timestamp(c.created_at),'updated_at',platform.catalog_timestamp(c.updated_at),'published_at',platform.catalog_timestamp(c.published_at),'deleted_at',platform.catalog_timestamp(c.deleted_at),'title',c.title,'volume',c.volume,'chapter',c.chapter,'language',c.language,'is_unavailable',c.is_unavailable,'version',c.version,'relationships',jsonb_build_object('uploader',jsonb_build_object('id',c.uploader_id,'name',c.uploader_name,'version',1),'manga',platform.catalog_manga_json(c.manga_id),'groups',COALESCE((SELECT jsonb_agg(platform.catalog_group_json(cg.group_id) ORDER BY cg.group_id) FROM platform.catalog_chapter_groups cg WHERE cg.chapter_id=c.id),'[]'::jsonb),'thread',platform.catalog_thread_json('chapter',c.id),'stats',jsonb_build_object('views',COALESCE(s.views,0))))) FROM platform.catalog_chapters c LEFT JOIN platform.catalog_chapter_counters s ON s.chapter_id=c.id WHERE c.id=value
$$;
CREATE INDEX catalog_manga_search_gin ON platform.catalog_manga USING GIN(to_tsvector('simple',title || ' ' || COALESCE(metadata->>'alt_titles','')));
